.icon-title{
    // 当user-select的时候禁用即可
    user-select: none;
	// 兼容Webkit
    -webkit-user-select: none;
	// 兼容IOS
    -webkit-touch-callout: none;
    height: auto;
    width: 64px;

    path{
        transition: fill 0.3s ease;
    }

}

.leftbar{
    display: flex;
    flex-direction: column;
    justify-content:center;
    align-items: center;

	// 标题样式
    .title{
        user-select: none;
        -webkit-user-select: none;
        -webkit-touch-callout: none;

		// 文字样式
        font-size:large;
        color: var(--el-color-primary);
        font-weight: 900;
    }

	// 分隔栏样式
    .divider{
        border: 1px solid var(--el-color-info);
        width: 70%;
    }
}


button {
    white-space: nowrap;
	// 设置button为行内样式
	border-radius: 4px;
    background-color: rgba(0,0,0,0);
	// border-style设置为none可以取消边框button的边框
	border: none;
	color: var(--text-secondary);
	text-align: center;
	font-size: 17px;
	width: 130px;
    font-weight: 500;
	cursor: pointer;
	margin: 5px;

	span{
		cursor: pointer;
		display: inline-block;
		position: relative;
		transition: 0.3s;
	}

	span:after{
		content: '»';
		position: relative;
		opacity: 0;
		top: 0;
		right: -4px;
		transition: 0.3s;
		vertical-align:10%;
	}

	&:hover span{
		&:after{
			opacity: 1;
			right: 0;
		}
	}

	&:hover{
		transform: translateX(-15px);
		transition: transform 0.3s ease;
	}
}
</style>

